sql.where:
r.is_deleted = false

    AND i.definition_id = #{definitionId}


    AND r.action = #{action}


    AND i.status = #{status}


    AND i.business_type = #{businessType}


    AND i.applicant_id = #{applicantId}


    AND r.approver_id = #{approverId}


    AND r.operate_time >= #{startTime}


    AND r.operate_time <= #{endTime}
